#### Baseline Mode
To make the analysis more robust, we account for natural weather fluctuations. Specifically, users can toggle “Seasonally adjusted data” from “Actual data”. This application then instantly switches the map and charts from raw data to data relative to the same month in 2019.

::: {.scroll-container style="overflow-y: scroll; height: 300px; padding:20px "}

```js
function refreshMap() {
 var isSameDate = (state.fromYear === state.toYear && state.fromMonth === state.toMonth);
 var isBaseline = (state.timeMode === 'adjusted');


 splitCheck.style().set('shown', !isSameDate || isBaseline);
 var actuallySplit = state.splitEnabled && (!isSameDate || isBaseline);


 var fromStr = MONTHS[state.fromMonth - 1] + ' ' + state.fromYear; var toStr = MONTHS[state.toMonth - 1] + ' ' + state.toYear;
 leftDateLabel.setValue(isBaseline ? 'Baseline 2019' : (isSameDate || actuallySplit ? fromStr : fromStr + ' → ' + toStr)); rightDateLabel.setValue(toStr);
 leftMap.layers().reset(); rightMap.layers().reset();


 if (actuallySplit) {
   if (containerMode !== 'split') { mapContainer.widgets().reset([splitPanel]); containerMode = 'split'; }
   rightDateLabel.style().set('shown', true);


   if (state.activeLayer === 'greenspace') {
     leftMap.addLayer(getFVCImage(state.fromYear, state.fromMonth), fvc_vis, 'FVC Before');
     rightMap.addLayer(getFVCImage(state.toYear, state.toMonth), fvc_vis, 'FVC After'); }
   else if (state.activeLayer === 'temperature') {
     leftMap.addLayer(getLSTImage(state.fromYear, state.fromMonth), lst_vis, 'LST Before');
     rightMap.addLayer(getLSTImage(state.toYear, state.toMonth), lst_vis, 'LST After'); }
   else if (state.activeLayer === 'water') {
     leftMap.addLayer(getETImage(state.fromYear, state.fromMonth), et_vis, 'Water Before');
     rightMap.addLayer(getETImage(state.toYear, state.toMonth), et_vis, 'Water After'); }
   else {
     leftMap.addLayer(getS2Composite(state.fromYear, state.fromMonth), s2_vis, 'S2 Before');
     rightMap.addLayer(getS2Composite(state.toYear, state.toMonth), s2_vis, 'S2 After'); }
 } else {
   if (containerMode !== 'single') { mapContainer.widgets().reset([leftMap]); containerMode = 'single'; }
   rightDateLabel.style().set('shown', false);
